def is_allowed_filelist_line(line: str) -> bool:
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
        return True
    if stripped.startswith("+incdir+"):
        return True
    if stripped.startswith("+"):
        return False
    return True

def sanitize_filelist_text(text: str) -> str:
    if not text:
        return text
    output_lines = []
    seen_entries = set()
    changed = False
    for line in text.splitlines():
        stripped = line.strip()
        if not is_allowed_filelist_line(line):
            changed = True
            continue
        if not stripped or stripped.startswith("#"):
            output_lines.append(line)
            continue
        normalized = stripped.replace("\", "/")
        if normalized in seen_entries:
            changed = True
            continue
        seen_entries.add(normalized)
        output_lines.append(line)
    if not changed:
        return text
    sanitized = "
".join(output_lines)
    if text.endswith("
"):
        sanitized += "
"
    return sanitized

def ensure_line_present(text: str, line: str) -> str:
    stripped_line = line.strip()
    if not stripped_line:
        return text
    existing = [item.strip().replace("\", "/") for item in text.splitlines() if item.strip()]
    if stripped_line.replace("\", "/") in existing:
        return text
    suffix = "" if text.endswith("
") or not text else "
"
    return sanitize_filelist_text(text + suffix + stripped_line + "
